  function draw() {
    // background
    drawBackground();
    // player with gradient and rounded corners
    const playerGrad = ctx.createLinearGradient(player.x, player.y, player.x, player.y + player.h);
    playerGrad.addColorStop(0, '#00ff00');
    playerGrad.addColorStop(1, '#007700');
    drawRoundedRect(player.x, player.y, player.w, player.h, 6, playerGrad);
    // blocks with gradient and rounded
    blocks.forEach(b => {
      const blockGrad = ctx.createLinearGradient(b.x, b.y, b.x, b.y + b.h);
      blockGrad.addColorStop(0, '#ff5555');
      blockGrad.addColorStop(1, '#aa0000');
      drawRoundedRect(b.x, b.y, b.w, b.h, 4, blockGrad);
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
      ctx.textAlign = 'start';
    }
  }
